export const insuranceBaselineHtml = "<!-- ===================== INSURANCE — SECTION SUB NAV (STICKY TABS) | CLONE OF HEALTHCARE ===================== -->\n    <link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n    \n    <style>\n      :root{\n        --navy:#020C4F;\n        --indigo:#313B86;\n        --violet:#625AD8;\n        --accent:#1F9CE4;\n    \n        --tabText:#6B7280;\n        --tabActive: var(--indigo);\n        --line:#E6E8EF;\n        --bg:#ffffff;\n    \n        /* ✅ Height of this subnav (kept as a variable for scroll offset) */\n        --secTabsH: 58px;\n      }\n    \n      .insTabs, .insTabs *{box-sizing:border-box;}\n    \n      /* ✅ Sticky subnav only (main header can stay non-sticky) */\n      .insTabs{\n        position:sticky;\n        top:0;\n        z-index:9999;\n        background:var(--bg);\n        border-bottom:1px solid var(--line);\n        font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n        isolation:isolate;\n      }\n    \n      .insTabs__inner{\n        max-width:1200px;\n        margin:0 auto;\n        padding:0 20px;\n        height:var(--secTabsH);\n        display:flex;\n        align-items:center;\n        gap:14px;\n      }\n    \n      .insTabs__label{\n        font-weight:900;\n        letter-spacing:.08em;\n        text-transform:uppercase;\n        color:#111;\n        font-size:12px;\n        padding-right:14px;\n        border-right:1px solid var(--line);\n        margin-right:2px;\n        white-space:nowrap;\n      }\n    \n      .insTabs__list{\n        display:flex;\n        align-items:center;\n        gap:0;\n        flex-wrap:nowrap;\n        overflow:auto;\n        scrollbar-width:none;\n      }\n      .insTabs__list::-webkit-scrollbar{display:none;}\n    \n      .insTabs__link{\n        position:relative;\n        display:inline-flex;\n        align-items:center;\n        height:var(--secTabsH);\n        padding:0 18px;\n        text-decoration:none;\n        text-transform:uppercase;\n        letter-spacing:.06em;\n        font-size:12px;\n        font-weight:800;\n        color:var(--tabText);\n        white-space:nowrap;\n      }\n    \n      /* vertical separators */\n      .insTabs__link + .insTabs__link{\n        border-left:1px solid var(--line);\n      }\n    \n      /* active underline */\n      .insTabs__link.is-active{\n        color:var(--tabActive);\n      }\n      .insTabs__link.is-active::after{\n        content:\"\";\n        position:absolute;\n        left:14px;\n        right:14px;\n        bottom:0;\n        height:3px;\n        background:var(--tabActive);\n        border-radius:999px;\n      }\n    \n      .insTabs__link:hover{ color:#111; }\n    \n      /* ✅ Optional: make the section itself \"reserve space\" so anchor jumps never hide behind sticky tabs */\n      /* Add this class to each target section wrapper if you want:\n         <section id=\"...\" class=\"insAnchorFix\"> ... */\n      .insAnchorFix{ scroll-margin-top: calc(var(--secTabsH) + 14px); }\n    \n      @media(max-width:980px){\n        .insTabs__inner{padding:0 14px;}\n        .insTabs__label{display:none;}\n        .insTabs__link{padding:0 14px;}\n      }\n    </style>\n    \n    <nav class=\"insTabs\" aria-label=\"Insurance page navigation\">\n      <div class=\"insTabs__inner\">\n        <div class=\"insTabs__label\">INSURANCE</div>\n    \n        <div class=\"insTabs__list\">\n          <!-- ✅ Update IDs to match your Insurance page section IDs -->\n          <a class=\"insTabs__link is-active\" href=\"#ins-hero\">Overview</a>\n          <a class=\"insTabs__link\" href=\"#insurance-context\">Context</a>\n          <a class=\"insTabs__link\" href=\"#insurance-challenges\">Key Challenges</a>\n          <a class=\"insTabs__link\" href=\"#insurance-how-we-help\">How We Help</a>\n          <a class=\"insTabs__link\" href=\"#insurance-why\">Why Us</a>\n          <a class=\"insTabs__link\" href=\"#insurance-cta\">Next Steps</a>\n        </div>\n      </div>\n    </nav>\n    \n    <script>\n    (function(){\n      const nav = document.querySelector('.insTabs');\n      if(!nav) return;\n    \n      const links = Array.from(nav.querySelectorAll('.insTabs__link'));\n      const getOffset = () => {\n        const h = nav.getBoundingClientRect().height || 58;\n        return h + 12; // ✅ small breathing space so title is visible\n      };\n    \n      // Smooth scroll with correct offset so sections are NOT hidden under sticky tabs\n      links.forEach(a=>{\n        a.addEventListener('click', (e)=>{\n          const href = a.getAttribute('href');\n          if(!href || !href.startsWith('#')) return;\n    \n          const el = document.querySelector(href);\n          if(!el) return;\n    \n          e.preventDefault();\n          const y = el.getBoundingClientRect().top + window.pageYOffset - getOffset();\n          window.scrollTo({ top:y, behavior:'smooth' });\n          history.replaceState(null, '', href);\n        });\n      });\n    \n      // Active state on scroll\n      const targets = links\n        .map(a => document.querySelector(a.getAttribute('href')))\n        .filter(Boolean);\n    \n      const setActive = (id) => {\n        links.forEach(a=>{\n          a.classList.toggle('is-active', a.getAttribute('href') === '#'+id);\n        });\n      };\n    \n      const isElementor =\n        document.body.classList.contains('elementor-editor-active') ||\n        document.body.classList.contains('elementor-editor-preview') ||\n        !!document.querySelector('#elementor-editor-wrapper');\n    \n      if(isElementor) return;\n      if(!('IntersectionObserver' in window)) return;\n    \n      const io = new IntersectionObserver((entries)=>{\n        // pick the entry closest to top that is visible\n        const visible = entries\n          .filter(e=>e.isIntersecting)\n          .sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];\n    \n        if(visible && visible.target && visible.target.id){\n          setActive(visible.target.id);\n        }\n      }, { root:null, threshold:[0.2,0.35,0.5,0.65] });\n    \n      targets.forEach(t=>{\n        if(t.id) io.observe(t);\n      });\n    })();\n    </script>\n\n<!-- ===================== INSURANCE — HERO (WHITE ONLY) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    /* ✅ only agreed brand colours */\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --ink:#0B0F1A;\n    --muted:#3C4160;\n    --line:rgba(49,59,134,.16);\n    --white:#ffffff;\n\n    --max:1200px;\n  }\n\n  .insHero, .insHero *{box-sizing:border-box;}\n  .insHero{\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    color:var(--ink);\n    background:#fff;\n    padding:88px 20px 34px;\n  }\n\n  .insHero__inner{\n    max-width:var(--max);\n    margin:0 auto;\n    display:grid;\n    grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);\n    gap:44px;\n    align-items:center;\n  }\n\n  .insHero__eyebrow{\n    margin:0 0 12px;\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n  }\n\n  .insHero__title{\n    margin:0 0 14px;\n    font-size:clamp(34px,4.2vw,56px);\n    line-height:1.06;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .insHero__sub{\n    margin:0 0 14px;\n    font-size:clamp(16px,2vw,20px);\n    line-height:1.55;\n    font-weight:700;\n    color:var(--indigo);\n    max-width:820px;\n  }\n\n  .insHero__p{\n    margin:0;\n    font-size:15.5px;\n    line-height:1.78;\n    color:var(--muted);\n    max-width:920px;\n  }\n  .insHero__p + .insHero__p{ margin-top:14px; }\n\n  /* Right visual (image placeholder) */\n  .insHero__media{\n    border-radius:22px;\n    overflow:hidden;\n    border:1px solid var(--line);\n    box-shadow:0 18px 44px rgba(0,0,0,.08);\n    background:\n      radial-gradient(circle at 20% 15%, rgba(98,90,216,.22), transparent 55%),\n      radial-gradient(circle at 85% 25%, rgba(31,156,228,.22), transparent 55%),\n      radial-gradient(circle at 50% 95%, rgba(49,59,134,.18), transparent 60%),\n      linear-gradient(180deg, rgba(2,12,79,.06), rgba(49,59,134,.04));\n    min-height:320px;\n    position:relative;\n  }\n\n  .insHero__img{\n    width:100%;\n    height:100%;\n    display:block;\n    object-fit:cover; /* ✅ fills container */\n  }\n\n  .insHero__badge{\n    position:absolute;\n    left:16px; top:16px;\n    display:inline-flex;\n    align-items:center;\n    gap:10px;\n    padding:10px 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.18);\n    background:rgba(255,255,255,.76);\n    backdrop-filter:blur(8px);\n    color:var(--navy);\n    font-size:12px;\n    font-weight:900;\n  }\n  .insHero__dot{\n    width:10px;height:10px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    box-shadow:0 0 0 5px rgba(31,156,228,.12);\n  }\n\n  @media (max-width:980px){\n    .insHero{padding:74px 16px 22px;}\n    .insHero__inner{grid-template-columns:1fr; gap:22px;}\n    .insHero__media{min-height:240px;}\n  }\n</style>\n\n<section class=\"insHero\" id=\"ins-hero\">\n  <div class=\"insHero__inner\">\n    <!-- LEFT CONTENT -->\n    <div>\n      <p class=\"insHero__eyebrow\">Insurance Sector – Industry Solutions &amp; Transformation Services</p>\n\n      <h1 class=\"insHero__title\">Reimagining Insurance Enterprises for Growth, Trust, and Operational Resilience</h1>\n\n      <p class=\"insHero__p\">\n        The Insurance sector is navigating a period of structural change—heightened customer expectations, margin pressure,\n        regulatory scrutiny, digital disruption, climate-driven risk volatility, and increasing competition from agile InsurTech players.\n        Insurers are expected to grow profitably while improving customer trust, accelerating claims resolution, and managing risk with far greater precision.\n      </p>\n    </div>\n\n    <!-- RIGHT VISUAL -->\n    <div class=\"insHero__media\">\n      <div class=\"insHero__badge\"><span class=\"insHero__dot\"></span> Insurance Transformation</div>\n      <img\n        class=\"insHero__img\"\n        src=\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\"\n        alt=\"Insurance enterprise transformation (placeholder)\"\n      />\n    </div>\n  </div>\n</section>\n\n<!-- ===================== INSURANCE — CONTEXT (WHITE BG + COLOURED CARD) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    --navy:#020C4F;\n    --ink:#0B0F1A;\n    --white:#ffffff;\n\n    /* Context card colour */\n    --context:#7C1F66;\n  }\n\n  .insCtx, .insCtx *{box-sizing:border-box;}\n\n  .insCtx{\n    background:#fff;\n    padding:34px 20px 86px;\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  }\n\n  .insCtx__inner{\n    max-width:1200px;\n    margin:0 auto;\n  }\n\n  .insCtx__card{\n    background:var(--context);\n    border-radius:24px;\n    padding:34px 36px;\n    box-shadow:0 22px 54px rgba(0,0,0,.22);\n    position:relative;\n    overflow:hidden;\n  }\n\n  /* subtle executive texture (very light, optional) */\n  .insCtx__card::before{\n    content:\"\";\n    position:absolute;\n    inset:0;\n    background:\n      radial-gradient(circle at 0% 0%, rgba(255,255,255,.08), transparent 60%),\n      radial-gradient(circle at 100% 100%, rgba(255,255,255,.06), transparent 60%);\n    pointer-events:none;\n  }\n\n  .insCtx__text{\n    margin:0;\n    max-width:1020px;\n    font-size:16px;\n    line-height:1.78;\n    font-weight:500;\n    color:#ffffff;\n    position:relative;\n    z-index:1;\n  }\n\n  @media (max-width:980px){\n    .insCtx{padding:26px 16px 74px;}\n    .insCtx__card{\n      padding:26px 22px;\n      border-radius:20px;\n    }\n    .insCtx__text{\n      font-size:15px;\n      line-height:1.72;\n    }\n  }\n</style>\n\n<section class=\"insCtx\" id=\"insurance-context\">\n  <div class=\"insCtx__inner\">\n    <div class=\"insCtx__card\">\n      <p class=\"insCtx__text\">\n        We partner with insurance organisations to convert fragmented operating models into integrated systems, and strategic ambition\n        into reliable execution across the value chain. Our integrated approach—spanning strategy, operations, digital enablement,\n        governance, and capability building—helps insurers build resilient, customer-centric, and future-ready enterprises.\n      </p>\n    </div>\n  </div>\n</section>\n\n<!-- ===================== INSURANCE — KEY CHALLENGES (DESKTOP: LIST + DETAIL | MOBILE: CARD ACCORDION) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --ink:#0B0F1A;\n    --muted:#4B5168;\n    --line:rgba(49,59,134,.16);\n    --card:#fff;\n  }\n\n  .insK, .insK *{ box-sizing:border-box; }\n\n  .insK{\n    position:relative;\n    padding:92px 20px;\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    color:var(--ink);\n    overflow:hidden;\n    background:\n      radial-gradient(circle at 18% 0%, rgba(98,90,216,.10), transparent 55%),\n      radial-gradient(circle at 95% 30%, rgba(49,59,134,.10), transparent 55%),\n      radial-gradient(circle at 70% 110%, rgba(2,12,79,.08), transparent 60%),\n      rgba(49,59,134,.03);\n  }\n\n  .insK__inner{ max-width:1200px; margin:0 auto; position:relative; }\n\n  .insK__top{\n    display:grid;\n    grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);\n    gap:32px;\n    align-items:start;\n    margin-bottom:22px;\n  }\n\n  .insK__eyebrow{\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n    margin:0 0 10px;\n  }\n\n  .insK__title{\n    margin:0;\n    font-size:clamp(38px,4.4vw,56px);\n    line-height:1.05;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .insK__intro{\n    margin:22px 0 0;\n    font-size:15.5px;\n    line-height:1.75;\n    color:#3C4160;\n    max-width:720px;\n  }\n\n  .insK__grid{\n    display:grid;\n    grid-template-columns:minmax(0,.86fr) minmax(0,1.14fr);\n    gap:26px;\n    align-items:stretch;\n    margin-top:18px;\n  }\n\n  /* LEFT RAIL (desktop/tablet) */\n  .insK__rail{\n    border:1px solid rgba(49,59,134,.18);\n    border-radius:22px;\n    background:rgba(255,255,255,.78);\n    backdrop-filter:blur(10px);\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n    overflow:hidden;\n    min-width:0;\n  }\n\n  .insK__railTop{\n    display:flex;\n    align-items:center;\n    justify-content:space-between;\n    gap:14px;\n    padding:16px 16px;\n    border-bottom:1px solid rgba(49,59,134,.12);\n  }\n\n  .insK__railLabel{\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--navy);\n    font-weight:900;\n  }\n\n  .insK__railPill{\n    display:inline-flex;\n    align-items:center;\n    gap:8px;\n    height:32px;\n    padding:0 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.16);\n    background:rgba(255,255,255,.85);\n    font-size:12px;\n    font-weight:800;\n    color:var(--indigo);\n    white-space:nowrap;\n  }\n  .insK__railPillDot{\n    width:10px;height:10px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    box-shadow:0 0 0 5px rgba(31,156,228,.10);\n  }\n\n  .insK__item{\n    width:100%;\n    display:grid;\n    grid-template-columns:44px 1fr;\n    gap:12px;\n    align-items:center;\n    padding:14px 16px;\n    background:transparent;\n    border:0;\n    border-top:1px solid rgba(49,59,134,.10);\n    cursor:pointer;\n    text-align:left;\n    transition:background .18s ease;\n    min-width:0;\n\n    /* critical: some themes force button nowrap */\n    white-space:normal !important;\n  }\n  .insK__item:first-of-type{ border-top:0; }\n  .insK__item:hover{ background:rgba(49,59,134,.03); }\n\n  .insK__icon{\n    width:40px;height:40px;\n    border-radius:14px;\n    display:grid;\n    place-items:center;\n    background:rgba(49,59,134,.05);\n    border:1px solid rgba(49,59,134,.14);\n    font-size:16px;\n  }\n\n  .insK__textCol{ min-width:0 !important; }\n\n  .insK__itemTitle{\n    margin:0;\n    font-size:14.5px;\n    font-weight:900;\n    color:var(--navy);\n    line-height:1.25;\n    white-space:normal !important;\n    overflow-wrap:anywhere !important;\n    word-break:break-word !important;\n    max-width:100% !important;\n  }\n\n  /* ✅ 2-line preview enforced */\n  .insK__itemPreview{\n    margin:4px 0 0;\n    font-size:13px;\n    line-height:1.5;\n    color:#5B6282;\n\n    display:-webkit-box !important;\n    -webkit-box-orient:vertical !important;\n    -webkit-line-clamp:2 !important;\n    overflow:hidden !important;\n    text-overflow:ellipsis !important;\n    white-space:normal !important;\n\n    overflow-wrap:anywhere !important;\n    word-break:break-word !important;\n    min-width:0;\n    max-width:100%;\n  }\n\n  /* Accordion content hidden by default (desktop/tablet) */\n  .insK__acc{ display:none; }\n\n  .insK__item[aria-selected=\"true\"]{\n    background:rgba(31,156,228,.06);\n    position:relative;\n  }\n  .insK__item[aria-selected=\"true\"]::before{\n    content:\"\";\n    position:absolute;\n    left:0; top:0; bottom:0;\n    width:4px;\n    background:linear-gradient(180deg,var(--accent),var(--violet));\n  }\n  .insK__item[aria-selected=\"true\"] .insK__icon{\n    border-color:rgba(31,156,228,.28);\n    background:rgba(31,156,228,.08);\n  }\n\n  /* RIGHT PANEL (desktop/tablet) */\n  .insK__panel{\n    border:1px solid rgba(49,59,134,.18);\n    border-radius:22px;\n    background:rgba(255,255,255,.86);\n    backdrop-filter:blur(10px);\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n    overflow:hidden;\n    display:flex;\n    flex-direction:column;\n    min-width:0;\n    min-height:520px;\n  }\n\n  .insK__panelHead{\n    padding:16px 18px 14px;\n    border-bottom:1px solid rgba(49,59,134,.12);\n    background:\n      radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 60%),\n      rgba(255,255,255,.85);\n  }\n\n  .insK__panelKicker{\n    margin:0 0 6px;\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n  }\n\n  .insK__panelTitle{\n    margin:0;\n    font-size:22px;\n    line-height:1.25;\n    font-weight:950;\n    color:var(--navy);\n  }\n\n  .insK__panelBody{ padding:18px; flex:1 1 auto; }\n\n  .insK__bullets{\n    margin:0;\n    padding:0;\n    list-style:none;\n    display:grid;\n    gap:12px;\n  }\n\n  .insK__bullets li{\n    display:flex;\n    gap:10px;\n    align-items:flex-start;\n    font-size:14.5px;\n    line-height:1.65;\n    color:#2E334D;\n    min-width:0;\n  }\n\n  .insK__dot{\n    width:10px;height:10px;border-radius:999px;\n    margin-top:7px;\n    flex:0 0 auto;\n    background:rgba(31,156,228,.22);\n    outline:3px solid rgba(31,156,228,.10);\n  }\n\n  .insK__bullets li span:last-child{\n    min-width:0;\n    overflow-wrap:anywhere;\n    word-break:break-word;\n  }\n\n  .insK__panelFooter{\n    padding:14px 16px;\n    border-top:1px solid rgba(49,59,134,.12);\n    background:rgba(255,255,255,.75);\n    display:flex;\n    flex-wrap:wrap;\n    gap:10px;\n  }\n\n  .insK__chip{\n    display:inline-flex;\n    align-items:center;\n    gap:8px;\n    height:34px;\n    padding:0 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.16);\n    background:rgba(255,255,255,.9);\n    color:var(--navy);\n    font-size:12px;\n    font-weight:800;\n    max-width:100%;\n  }\n  .insK__chip i{\n    width:7px;height:7px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    display:inline-block;\n  }\n\n  .insK__fade{\n    opacity:1;\n    transform:translateY(0);\n    transition:opacity .18s ease, transform .18s ease;\n  }\n  .insK__fade.is-switching{\n    opacity:0;\n    transform:translateY(6px);\n  }\n\n  @media (max-width:1024px){\n    .insK{ padding:78px 18px; }\n    .insK__top{ grid-template-columns:1fr; gap:14px; }\n    .insK__intro{ margin-top:0; }\n    .insK__grid{ grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr); gap:18px; }\n    .insK__panel{ min-height:unset; }\n  }\n\n  /* ===================== MOBILE: stacked card accordion ===================== */\n  @media (max-width:820px){\n    .insK{ padding:70px 16px; }\n    .insK__title{ font-size:clamp(30px,9vw,40px); }\n    .insK__intro{ font-size:14.8px; margin-top:10px; }\n\n    .insK__grid{ grid-template-columns:1fr; }\n\n    /* Hide the right panel on mobile */\n    .insK__panel{ display:none !important; }\n\n    /* Remove the big “rail frame” on mobile */\n    .insK__rail{\n      border:none;\n      background:transparent;\n      backdrop-filter:none;\n      box-shadow:none;\n      overflow:visible;\n    }\n\n    /* Small header pill bar */\n    .insK__railTop{\n      padding:14px 14px;\n      border:1px solid rgba(49,59,134,.16);\n      border-radius:18px;\n      background:rgba(255,255,255,.86);\n      box-shadow:0 10px 26px rgba(0,0,0,.06);\n      margin-bottom:12px;\n    }\n\n    /* Each item becomes its own card */\n    .insK__item{\n      border:1px solid rgba(49,59,134,.14);\n      border-radius:18px;\n      background:rgba(255,255,255,.86);\n      box-shadow:0 12px 28px rgba(0,0,0,.06);\n      margin:0 0 12px;\n      padding:14px 14px;\n      grid-template-columns:42px 1fr;\n      align-items:start;\n      max-width:100% !important;\n    }\n    .insK__item:first-of-type{ border-top:1px solid rgba(49,59,134,.14); }\n\n    .insK__icon{ width:38px;height:38px; border-radius:14px; margin-top:2px; }\n\n    /* kill desktop selected styling on mobile */\n    .insK__item[aria-selected=\"true\"]{ background:rgba(255,255,255,.86) !important; }\n    .insK__item[aria-selected=\"true\"]::before{ display:none !important; }\n\n    /* Accordion body */\n    .insK__acc{\n      grid-column:1 / -1;\n      margin:10px 0 2px;\n      padding:12px 12px;\n      border-radius:16px;\n      border:1px solid rgba(49,59,134,.12);\n      background:rgba(49,59,134,.03);\n      display:none;\n      overflow:hidden !important;\n      max-width:100% !important;\n      min-width:0 !important;\n    }\n    .insK__item[aria-expanded=\"true\"] .insK__acc{ display:block; }\n\n    .insK__accBullets{\n      margin:0;\n      padding:0;\n      list-style:none;\n      display:grid;\n      gap:10px;\n      max-width:100% !important;\n      min-width:0 !important;\n    }\n    .insK__accBullets li{\n      display:flex !important;\n      align-items:flex-start !important;\n      gap:10px !important;\n      flex-wrap:wrap !important;\n      min-width:0 !important;\n      max-width:100% !important;\n      font-size:14px;\n      line-height:1.65;\n      color:#2E334D;\n    }\n    .insK__accBullets li .insK__dot{ flex:0 0 auto !important; }\n\n    /* text span wraps correctly */\n    .insK__accBullets li span:last-child{\n      flex:1 1 0% !important;\n      min-width:0 !important;\n      max-width:100% !important;\n      display:block !important;\n      white-space:normal !important;\n      overflow-wrap:anywhere !important;\n      word-break:break-word !important;\n    }\n\n    .insK__accChips{\n      margin-top:12px;\n      display:flex;\n      flex-wrap:wrap;\n      gap:10px;\n      max-width:100%;\n    }\n\n    .insK__chip{ height:32px; font-size:12px; padding:0 11px; }\n  }\n\n  /* ===================== FORCE MOBILE LAYOUT VIA CLASS (Elementor preview help) ===================== */\n  .insK.is-mobile{ padding:70px 16px !important; }\n  .insK.is-mobile .insK__grid{ grid-template-columns:1fr !important; }\n  .insK.is-mobile .insK__panel{ display:none !important; }\n  .insK.is-mobile .insK__rail{\n    border:none !important; background:transparent !important; box-shadow:none !important;\n    backdrop-filter:none !important; overflow:visible !important;\n  }\n  .insK.is-mobile .insK__railTop{\n    padding:14px 14px !important;\n    border:1px solid rgba(49,59,134,.14) !important;\n    border-radius:16px !important;\n    background:#fff !important;\n    box-shadow:0 10px 24px rgba(0,0,0,.06) !important;\n    margin-bottom:12px !important;\n  }\n  .insK.is-mobile .insK__item{\n    border:1px solid rgba(49,59,134,.12) !important;\n    border-radius:16px !important;\n    background:#fff !important;\n    box-shadow:0 12px 26px rgba(0,0,0,.06) !important;\n    margin:0 0 12px !important;\n    padding:14px 14px !important;\n    grid-template-columns:42px 1fr !important;\n    align-items:start !important;\n  }\n  .insK.is-mobile .insK__item[aria-selected=\"true\"]::before{ display:none !important; }\n  .insK.is-mobile .insK__item[aria-selected=\"true\"]{ background:#fff !important; }\n  .insK.is-mobile .insK__acc{\n    display:none;\n    grid-column:1 / -1;\n    margin:10px 0 0;\n    padding:12px 12px;\n    border-radius:14px;\n    border:1px solid rgba(49,59,134,.10);\n    background:rgba(49,59,134,.02);\n    overflow:hidden !important;\n  }\n  .insK.is-mobile .insK__item[aria-expanded=\"true\"] .insK__acc{ display:block !important; }\n  .insK.is-mobile .insK__chip{ height:32px !important; font-size:12px !important; padding:0 11px !important; }\n</style>\n\n<section class=\"insK\" id=\"insurance-challenges\">\n  <div class=\"insK__inner\">\n\n    <div class=\"insK__top\">\n      <div>\n        <p class=\"insK__eyebrow\">Insurance Sector</p>\n        <h2 class=\"insK__title\">Key Challenges</h2>\n      </div>\n\n      <p class=\"insK__intro\">\n        Insurers are expected to grow profitably while improving trust, accelerating claims resolution, and managing risk\n        with far greater precision. Here are the critical pressure points we help solve.\n      </p>\n    </div>\n\n    <div class=\"insK__grid\">\n\n      <div class=\"insK__rail\" role=\"tablist\" aria-label=\"Insurance challenges list\">\n        <div class=\"insK__railTop\">\n          <div class=\"insK__railLabel\">Challenges</div>\n          <div class=\"insK__railPill\"><span class=\"insK__railPillDot\" aria-hidden=\"true\"></span>Executive view</div>\n        </div>\n\n        <button class=\"insK__item\" role=\"tab\" aria-selected=\"true\" aria-expanded=\"false\" data-key=\"c1\">\n          <div class=\"insK__icon\">📈</div>\n          <div class=\"insK__textCol\">\n            <p class=\"insK__itemTitle\">Growth, Profitability &amp; Market Pressure</p>\n            <p class=\"insK__itemPreview\">Slowing premium growth, rising competition, weaker cross-sell performance, and pressure on underwriting margins.</p>\n          </div>\n          <div class=\"insK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"insK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c2\">\n          <div class=\"insK__icon\">⚙️</div>\n          <div class=\"insK__textCol\">\n            <p class=\"insK__itemTitle\">Operational Inefficiencies &amp; Cost Stress</p>\n            <p class=\"insK__itemPreview\">Fragmented operations, high manual effort, long turnaround times, and rising expense ratios with limited transparency.</p>\n          </div>\n          <div class=\"insK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"insK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c3\">\n          <div class=\"insK__icon\">🛡️</div>\n          <div class=\"insK__textCol\">\n            <p class=\"insK__itemTitle\">Claims, Risk &amp; Loss Management Challenges</p>\n            <p class=\"insK__itemPreview\">Claims leakage and fraud risk, catastrophe-driven volatility, and weak integration across underwriting, claims, and actuarial.</p>\n          </div>\n          <div class=\"insK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"insK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c4\">\n          <div class=\"insK__icon\">📜</div>\n          <div class=\"insK__textCol\">\n            <p class=\"insK__itemTitle\">Regulatory, Compliance &amp; Governance Complexity</p>\n            <p class=\"insK__itemPreview\">Higher scrutiny, heavy reporting effort, fragmented controls, and limited real-time visibility into enterprise risk exposure.</p>\n          </div>\n          <div class=\"insK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"insK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c5\">\n          <div class=\"insK__icon\">💻</div>\n          <div class=\"insK__textCol\">\n            <p class=\"insK__itemTitle\">Digital, Data &amp; Technology Gaps</p>\n            <p class=\"insK__itemPreview\">Legacy core systems, disconnected data, underused analytics/AI for pricing and fraud, and challenges scaling secure digital channels.</p>\n          </div>\n          <div class=\"insK__acc\" aria-hidden=\"true\"></div>\n        </button>\n      </div>\n\n      <!-- Desktop panel only -->\n      <aside class=\"insK__panel\" role=\"tabpanel\" aria-live=\"polite\">\n        <div class=\"insK__fade\" id=\"insK-fade\">\n          <div class=\"insK__panelHead\">\n            <p class=\"insK__panelKicker\">Challenge Focus</p>\n            <h3 class=\"insK__panelTitle\" id=\"insK-title\">Growth, Profitability &amp; Market Pressure</h3>\n          </div>\n\n          <div class=\"insK__panelBody\">\n            <ul class=\"insK__bullets\" id=\"insK-bullets\"></ul>\n          </div>\n\n          <div class=\"insK__panelFooter\" id=\"insK-chips\"></div>\n        </div>\n      </aside>\n\n    </div>\n  </div>\n</section>\n\n<script>\n(function(){\n  const data = {\n    c1:{\n      title:\"Growth, Profitability & Market Pressure\",\n      bullets:[\n        \"Slowing premium growth and increasing price sensitivity\",\n        \"Rising competition from digital-first insurers and aggregators\",\n        \"Limited cross-sell and up-sell effectiveness\",\n        \"Pressure to improve combined ratios and underwriting margins\"\n      ],\n      chips:[\"Premium growth\",\"Underwriting margin\",\"Cross-sell/upsell\"]\n    },\n    c2:{\n      title:\"Operational Inefficiencies & Cost Stress\",\n      bullets:[\n        \"Fragmented processes across underwriting, policy servicing, and claims\",\n        \"High manual effort in back-office and middle-office operations\",\n        \"Long turnaround times impacting customer satisfaction\",\n        \"Rising expense ratios and limited cost transparency\"\n      ],\n      chips:[\"Ops simplification\",\"Cost transparency\",\"Turnaround time\"]\n    },\n    c3:{\n      title:\"Claims, Risk & Loss Management Challenges\",\n      bullets:[\n        \"Inconsistent claims outcomes and leakage\",\n        \"Fraud risk and weak early-warning mechanisms\",\n        \"Climate and catastrophe-driven loss volatility\",\n        \"Limited integration between underwriting, claims, and actuarial insights\"\n      ],\n      chips:[\"Claims leakage\",\"Fraud controls\",\"Cat risk\"]\n    },\n    c4:{\n      title:\"Regulatory, Compliance & Governance Complexity\",\n      bullets:[\n        \"Increasing regulatory scrutiny and reporting requirements\",\n        \"High effort in compliance, audits, and data reconciliation\",\n        \"Fragmented risk and control frameworks\",\n        \"Limited real-time visibility into enterprise risk exposure\"\n      ],\n      chips:[\"Compliance\",\"Risk & controls\",\"Governance\"]\n    },\n    c5:{\n      title:\"Digital, Data & Technology Gaps\",\n      bullets:[\n        \"Legacy core systems limiting agility and product innovation\",\n        \"Disconnected data across policy, claims, finance, and customer systems\",\n        \"Underutilisation of analytics and AI for pricing, risk, and fraud\",\n        \"Challenges in scaling automation and digital channels securely\"\n      ],\n      chips:[\"Core modernisation\",\"Data integration\",\"AI/analytics\"]\n    }\n  };\n\n  const root = document.querySelector('#insurance-challenges');\n  if(!root) return;\n\n  function applyMobileClass(){\n    const mqMobile = window.matchMedia && window.matchMedia('(max-width: 820px)').matches;\n\n    // Elementor responsive preview helpers\n    const elMobile =\n      document.body.classList.contains('elementor-device-mobile') ||\n      document.body.classList.contains('e--ua-device-mobile');\n\n    const mobile = mqMobile || elMobile;\n\n    root.classList.toggle('is-mobile', mobile);\n    return mobile;\n  }\n  applyMobileClass();\n  window.addEventListener('resize', applyMobileClass);\n\n  const tabs = Array.from(root.querySelectorAll('.insK__item'));\n  const fade = root.querySelector('#insK-fade');\n  const title = root.querySelector('#insK-title');\n  const bullets = root.querySelector('#insK-bullets');\n  const chips = root.querySelector('#insK-chips');\n\n  function isMobile(){\n    return (window.matchMedia && window.matchMedia('(max-width: 820px)').matches) || root.classList.contains('is-mobile');\n  }\n\n  function renderDesktop(key){\n    const d = data[key];\n    if(!d || !fade) return;\n\n    fade.classList.add('is-switching');\n    setTimeout(()=>{\n      title.textContent = d.title;\n\n      bullets.innerHTML = d.bullets.map(x =>\n        `<li><span class=\"insK__dot\"></span><span>${x}</span></li>`\n      ).join('');\n\n      chips.innerHTML = d.chips.map(x =>\n        `<span class=\"insK__chip\"><i></i>${x}</span>`\n      ).join('');\n\n      fade.classList.remove('is-switching');\n    }, 160);\n  }\n\n  function renderAccordionItem(btn){\n    const key = btn.dataset.key;\n    const d = data[key];\n    if(!d) return;\n\n    const acc = btn.querySelector('.insK__acc');\n    if(!acc) return;\n\n    acc.innerHTML = `\n      <ul class=\"insK__accBullets\">\n        ${d.bullets.map(x => `<li><span class=\"insK__dot\"></span><span>${x}</span></li>`).join('')}\n      </ul>\n      <div class=\"insK__accChips\">\n        ${d.chips.map(x => `<span class=\"insK__chip\"><i></i>${x}</span>`).join('')}\n      </div>\n    `;\n  }\n\n  tabs.forEach(btn => renderAccordionItem(btn));\n\n  function setActive(btn){\n    tabs.forEach(x=>{\n      x.setAttribute('aria-selected','false');\n      x.setAttribute('aria-expanded','false');\n    });\n    btn.setAttribute('aria-selected','true');\n\n    if(isMobile()){\n      btn.setAttribute('aria-expanded','true');\n    }else{\n      btn.setAttribute('aria-expanded','false');\n      renderDesktop(btn.dataset.key);\n    }\n  }\n\n  // Desktop default\n  renderDesktop('c1');\n\n  // Mobile: open first card by default\n  if(isMobile()){\n    tabs.forEach(x=>{\n      x.setAttribute('aria-selected','false');\n      x.setAttribute('aria-expanded','false');\n    });\n    tabs[0].setAttribute('aria-selected','true');\n    tabs[0].setAttribute('aria-expanded','true');\n  }\n\n  tabs.forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      if(isMobile()){\n        const expanded = btn.getAttribute('aria-expanded') === 'true';\n        if(expanded){\n          btn.setAttribute('aria-expanded','false');\n          return;\n        }\n        tabs.forEach(x=>x.setAttribute('aria-expanded','false'));\n        btn.setAttribute('aria-expanded','true');\n\n        tabs.forEach(x=>x.setAttribute('aria-selected','false'));\n        btn.setAttribute('aria-selected','true');\n      }else{\n        setActive(btn);\n      }\n    });\n  });\n\n  window.addEventListener('resize', ()=>{\n    const active = tabs.find(x => x.getAttribute('aria-selected') === 'true') || tabs[0];\n    if(!isMobile()){\n      renderDesktop(active.dataset.key || 'c1');\n    }\n  });\n})();\n</script>\n\n<!-- ===================== INSURANCE — HOW WE HELP (DESKTOP SLIDER + MOBILE ACCORDION) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#4B5168;\n  --line:rgba(49,59,134,.18);\n  --card:#ffffff;\n\n  --inh-bg-img:url(\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\");\n}\n\n/* scope */\n.inhS, .inhS *{ box-sizing:border-box; }\n\n.inhS{\n  position:relative;\n  padding:96px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  color:var(--ink);\n  overflow:hidden;\n\n  background:\n    radial-gradient(circle at 18% 0%, rgba(98,90,216,.10), transparent 55%),\n    radial-gradient(circle at 95% 30%, rgba(31,156,228,.10), transparent 55%),\n    radial-gradient(circle at 70% 110%, rgba(2,12,79,.08), transparent 60%),\n    rgba(49,59,134,.03);\n}\n\n.inhS::before{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  background:\n    linear-gradient(90deg, rgba(2,12,79,.80), rgba(2,12,79,.25) 55%, rgba(2,12,79,0) 100%),\n    var(--inh-bg-img);\n  background-size:cover;\n  background-position:center;\n  opacity:.95;\n  z-index:0;\n  pointer-events:none;\n}\n\n.inhS::after{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02));\n  z-index:0;\n  pointer-events:none;\n}\n\n.inhS__inner{\n  position:relative;\n  z-index:1;\n  max-width:1200px;\n  margin:0 auto;\n  width:100%;\n  min-width:0;\n}\n\n.inhS__eyebrow{\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:rgba(255,255,255,.85);\n  font-weight:800;\n  margin:0 0 10px;\n}\n\n.inhS__title{\n  margin:0 0 22px;\n  font-size:clamp(34px,4vw,56px);\n  line-height:1.08;\n  font-weight:900;\n  color:#fff;\n}\n\n.inhS__layout{\n  display:grid;\n  grid-template-columns:minmax(0,0.38fr) minmax(0,0.62fr);\n  gap:56px;\n  align-items:stretch;\n  width:100%;\n  min-width:0;\n}\n\n/* entrance animation */\n.inhS__left,\n.inhS__right{\n  opacity:0;\n  transition:opacity .85s ease, transform .85s cubic-bezier(.2,.9,.2,1);\n}\n.inhS__left{ transform:translateX(-44px); }\n.inhS__right{ transform:translateX(44px); }\n.inhS.is-in .inhS__left,\n.inhS.is-in .inhS__right{\n  opacity:1;\n  transform:translateX(0);\n}\n\n/* ===================== DESKTOP LEFT ===================== */\n.inhS__left{\n  border:1px solid rgba(255,255,255,.16);\n  border-radius:20px;\n  background:rgba(255,255,255,.06);\n  backdrop-filter: blur(10px);\n  box-shadow:0 12px 32px rgba(0,0,0,.14);\n  padding:18px;\n  min-width:0;\n}\n\n.inhS__leftTitle{\n  margin:0 0 12px;\n  font-size:26px;\n  font-weight:900;\n  color:#fff;\n}\n\n.inhS__nav{\n  display:grid;\n  gap:10px;\n  margin-top:10px;\n  min-width:0;\n}\n\n.inhS__navBtn{\n  width:100%;\n  border:1px solid rgba(255,255,255,.14);\n  background:rgba(255,255,255,.05);\n  border-radius:14px;\n  padding:14px 14px;\n  cursor:pointer;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:12px;\n  text-align:left;\n  transition:transform .18s ease, background .18s ease, border-color .18s ease;\n  min-width:0;\n}\n\n.inhS__navBtn:hover{\n  transform:translateY(-1px);\n  background:rgba(255,255,255,.07);\n  border-color:rgba(255,255,255,.18);\n}\n\n.inhS__navLeft{\n  display:flex;\n  align-items:center;\n  gap:10px;\n  min-width:0;\n  flex:1 1 auto;\n}\n\n.inhS__navMark{\n  width:10px; height:10px;\n  border-radius:999px;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.12);\n  flex:0 0 auto;\n}\n\n.inhS__navText{ min-width:0; }\n\n.inhS__itemTitle{\n  margin:0;\n  font-size:14.5px;\n  font-weight:800;\n  color:#fff;\n  line-height:1.2;\n  white-space:nowrap;\n  overflow:hidden;\n  text-overflow:ellipsis;\n}\n\n.inhS__itemHint{\n  margin:6px 0 0;\n  font-size:12.5px;\n  color:rgba(255,255,255,.80);\n  line-height:1.3;\n  white-space:nowrap;\n  overflow:hidden;\n  text-overflow:ellipsis;\n}\n\n.inhS__navArrow{\n  width:34px; height:34px;\n  border-radius:12px;\n  display:grid;\n  place-items:center;\n  border:1px solid rgba(255,255,255,.16);\n  color:#fff;\n  background:rgba(255,255,255,.06);\n  flex:0 0 auto;\n}\n\n.inhS__navBtn[aria-selected=\"true\"]{\n  background:rgba(255,255,255,.10);\n  border-color:rgba(255,255,255,.24);\n}\n\n/* ===================== DESKTOP RIGHT SLIDER ===================== */\n.inhS__right{\n  position:relative;\n  border-radius:22px;\n  min-height:560px;\n  min-width:0;\n}\n\n.inhS__stage{\n  position:relative;\n  height:100%;\n  min-height:560px;\n  padding:0 68px; /* peeks */\n  min-width:0;\n}\n\n.inhS__card{\n  position:absolute;\n  top:0;\n  left:50%;\n  transform:translateX(-50%);\n  width:86%;\n  height:100%;\n  border-radius:22px;\n  background:rgba(255,255,255,.96);\n  border:1px solid rgba(49,59,134,.18);\n  box-shadow:0 28px 70px rgba(0,0,0,.22);\n  overflow:hidden;\n  display:flex;\n  flex-direction:column;\n  transition:transform .42s cubic-bezier(.2,.9,.2,1), opacity .25s ease;\n}\n\n.inhS__card.is-active{ z-index:3; opacity:1; }\n.inhS__card.is-prev,\n.inhS__card.is-next{\n  z-index:2;\n  width:82%;\n  opacity:.78;\n  background:rgba(255,255,255,.78);\n  box-shadow:0 22px 60px rgba(0,0,0,.18);\n}\n.inhS__card.is-prev{ transform:translateX(-50%) translateX(-110px) scale(.965); }\n.inhS__card.is-next{ transform:translateX(-50%) translateX(110px) scale(.965); }\n\n.inhS__top{\n  padding:18px 22px 14px;\n  border-bottom:1px solid rgba(49,59,134,.14);\n  background:\n    radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 55%),\n    radial-gradient(circle at 100% 0%, rgba(31,156,228,.10), transparent 55%),\n    #fff;\n}\n\n.inhS__kicker{\n  margin:0 0 6px;\n  font-size:12px;\n  letter-spacing:.16em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:900;\n}\n\n.inhS__cardTitle{\n  margin:0;\n  font-size:22px;\n  line-height:1.2;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.inhS__body{\n  padding:16px 22px 18px;\n  overflow:auto;\n}\n\n.inhS__lead{\n  margin:0 0 12px;\n  font-size:15px;\n  line-height:1.75;\n  color:#2E334D;\n}\n\n.inhS__label{\n  margin:12px 0 8px;\n  font-size:14px;\n  font-weight:800;\n  color:var(--ink);\n}\n\n.inhS__list{ margin:0; padding-left:18px; }\n.inhS__list li{\n  margin:0 0 7px;\n  font-size:14.5px;\n  line-height:1.65;\n  color:#2E334D;\n}\n\n.inhS__impact{\n  margin-top:14px;\n  padding:12px 12px;\n  border-radius:14px;\n  border:1px solid rgba(49,59,134,.12);\n  background:rgba(49,59,134,.03);\n  border-left:4px solid var(--accent);\n  font-size:14.5px;\n  line-height:1.7;\n  color:#3C4160;\n}\n.inhS__impact b{ color:var(--navy); }\n\n/* peek preview */\n.inhS__card.is-prev .inhS__lead,\n.inhS__card.is-next .inhS__lead{\n  display:-webkit-box;\n  -webkit-line-clamp:2;\n  -webkit-box-orient:vertical;\n  overflow:hidden;\n  max-height:3.7em;\n}\n.inhS__card.is-prev .inhS__label,\n.inhS__card.is-next .inhS__label,\n.inhS__card.is-prev .inhS__list,\n.inhS__card.is-next .inhS__list,\n.inhS__card.is-prev .inhS__impact,\n.inhS__card.is-next .inhS__impact{\n  display:none;\n}\n\n.inhS__ctrl{\n  position:absolute;\n  top:50%;\n  transform:translateY(-50%);\n  width:46px;height:46px;\n  border-radius:14px;\n  border:1px solid rgba(255,255,255,.22);\n  background:rgba(0,0,0,.50);\n  color:#fff;\n  display:grid;\n  place-items:center;\n  cursor:pointer;\n  transition:transform .18s ease, background .18s ease, border-color .18s ease;\n  z-index:5;\n  user-select:none;\n}\n.inhS__ctrl:hover{\n  transform:translateY(-50%) scale(1.03);\n  background:rgba(255,255,255,.16);\n  border-color:rgba(255,255,255,.30);\n}\n.inhS__ctrl--prev{ left:12px; }\n.inhS__ctrl--next{ right:12px; }\n\n/* ===================== MOBILE DESIGN (NO HORIZONTAL ANYTHING) ===================== */\n.inhS__mWrap{ display:none; } /* only mobile */\n@media (max-width:980px){\n  .inhS{ padding:78px 16px; }\n  .inhS__layout{ grid-template-columns:1fr; gap:14px; }\n\n  /* hide desktop slider UI */\n  .inhS__right{ display:none !important; }\n\n  /* keep left header but change nav into vertical accordion cards */\n  .inhS__left{\n    padding:14px;\n    border-radius:18px;\n  }\n  .inhS__leftTitle{ font-size:18px; margin-bottom:10px; }\n\n  .inhS__nav{\n    display:none !important; /* hide desktop list */\n  }\n\n  /* show mobile accordion */\n  .inhS__mWrap{ display:grid; gap:12px; }\n\n  .inhS__mCard{\n    border:1px solid rgba(255,255,255,.18);\n    background:rgba(255,255,255,.08);\n    backdrop-filter: blur(10px);\n    border-radius:18px;\n    box-shadow:0 12px 28px rgba(0,0,0,.14);\n    overflow:hidden;\n  }\n\n  .inhS__mBtn{\n    width:100%;\n    border:0;\n    background:transparent;\n    padding:14px 14px;\n    display:flex;\n    align-items:center;\n    justify-content:space-between;\n    gap:12px;\n    cursor:pointer;\n    text-align:left;\n    color:#fff;\n  }\n\n  .inhS__mLeft{\n    display:flex;\n    align-items:flex-start;\n    gap:10px;\n    min-width:0;\n    flex:1 1 auto;\n  }\n\n  .inhS__mTitle{\n    margin:0;\n    font-size:14.5px;\n    font-weight:900;\n    line-height:1.25;\n    color:#fff;\n  }\n\n  .inhS__mHint{\n    margin:6px 0 0;\n    font-size:12.5px;\n    line-height:1.35;\n    color:rgba(255,255,255,.82);\n    overflow-wrap:anywhere;\n  }\n\n  .inhS__mChevron{\n    width:34px;height:34px;\n    border-radius:12px;\n    border:1px solid rgba(255,255,255,.16);\n    background:rgba(255,255,255,.06);\n    display:grid;\n    place-items:center;\n    color:#fff;\n    flex:0 0 auto;\n    transition:transform .2s ease;\n  }\n\n  .inhS__mAcc{\n    display:none;\n    padding:0 14px 14px;\n  }\n\n  .inhS__mCard[aria-expanded=\"true\"] .inhS__mAcc{ display:block; }\n  .inhS__mCard[aria-expanded=\"true\"] .inhS__mChevron{ transform:rotate(180deg); }\n\n  /* mobile content card (white) */\n  .inhS__mContent{\n    border-radius:16px;\n    background:rgba(255,255,255,.96);\n    border:1px solid rgba(49,59,134,.18);\n    box-shadow:0 18px 44px rgba(0,0,0,.18);\n    overflow:hidden;\n  }\n\n  .inhS__mTop{\n    padding:14px 14px 12px;\n    border-bottom:1px solid rgba(49,59,134,.14);\n    background:\n      radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 55%),\n      radial-gradient(circle at 100% 0%, rgba(31,156,228,.10), transparent 55%),\n      #fff;\n  }\n\n  .inhS__mKicker{\n    margin:0 0 6px;\n    font-size:11.5px;\n    letter-spacing:.14em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n  }\n\n  .inhS__mCardTitle{\n    margin:0;\n    font-size:20px;\n    line-height:1.2;\n    font-weight:950;\n    color:var(--navy);\n  }\n\n  .inhS__mBody{\n    padding:12px 14px 14px;\n  }\n\n  .inhS__mLead{\n    margin:0 0 10px;\n    font-size:14.5px;\n    line-height:1.7;\n    color:#2E334D;\n  }\n\n  .inhS__mLabel{\n    margin:10px 0 8px;\n    font-size:13.5px;\n    font-weight:900;\n    color:var(--ink);\n  }\n\n  .inhS__mList{\n    margin:0;\n    padding-left:18px;\n  }\n  .inhS__mList li{\n    margin:0 0 7px;\n    font-size:14.2px;\n    line-height:1.65;\n    color:#2E334D;\n    overflow-wrap:anywhere;\n  }\n\n  .inhS__mImpact{\n    margin-top:12px;\n    padding:10px 12px;\n    border-radius:14px;\n    border:1px solid rgba(49,59,134,.12);\n    background:rgba(49,59,134,.03);\n    border-left:4px solid var(--accent);\n    font-size:14.2px;\n    line-height:1.7;\n    color:#3C4160;\n  }\n  .inhS__mImpact b{ color:var(--navy); }\n}\n</style>\n\n<section class=\"inhS\" id=\"insurance-how-we-help\" aria-label=\"How we help insurance\">\n  <div class=\"inhS__inner\">\n    <p class=\"inhS__eyebrow\">Insurance Sector</p>\n    <h2 class=\"inhS__title\">How We Help the Insurance Sector</h2>\n\n    <div class=\"inhS__layout\">\n      <!-- DESKTOP LEFT -->\n      <aside class=\"inhS__left\">\n        <h3 class=\"inhS__leftTitle\">Our Services</h3>\n\n        <div class=\"inhS__nav\" role=\"tablist\" aria-label=\"Insurance services\">\n          <button class=\"inhS__navBtn\" role=\"tab\" aria-selected=\"true\" data-i=\"0\">\n            <div class=\"inhS__navLeft\">\n              <span class=\"inhS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"inhS__navText\">\n                <p class=\"inhS__itemTitle\">Growth &amp; Strategy</p>\n                <p class=\"inhS__itemHint\">Future-ready enterprise</p>\n              </div>\n            </div>\n            <span class=\"inhS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"inhS__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"1\">\n            <div class=\"inhS__navLeft\">\n              <span class=\"inhS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"inhS__navText\">\n                <p class=\"inhS__itemTitle\">Shared Services &amp; GCC Excellence</p>\n                <p class=\"inhS__itemHint\">Scaling operations</p>\n              </div>\n            </div>\n            <span class=\"inhS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"inhS__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"2\">\n            <div class=\"inhS__navLeft\">\n              <span class=\"inhS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"inhS__navText\">\n                <p class=\"inhS__itemTitle\">Tech-Enabled Transformation</p>\n                <p class=\"inhS__itemHint\">Digitising value chain</p>\n              </div>\n            </div>\n            <span class=\"inhS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"inhS__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"3\">\n            <div class=\"inhS__navLeft\">\n              <span class=\"inhS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"inhS__navText\">\n                <p class=\"inhS__itemTitle\">ESG, Sustainability &amp; Responsible Insurance</p>\n                <p class=\"inhS__itemHint\">Resilience &amp; trust</p>\n              </div>\n            </div>\n            <span class=\"inhS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"inhS__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"4\">\n            <div class=\"inhS__navLeft\">\n              <span class=\"inhS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"inhS__navText\">\n                <p class=\"inhS__itemTitle\">Business Process &amp; Operational Excellence</p>\n                <p class=\"inhS__itemHint\">Stable systems</p>\n              </div>\n            </div>\n            <span class=\"inhS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n        </div>\n\n        <!-- MOBILE ACCORDION -->\n        <div class=\"inhS__mWrap\" id=\"inhS-mobile\"></div>\n      </aside>\n\n      <!-- DESKTOP RIGHT -->\n      <div class=\"inhS__right\">\n        <button class=\"inhS__ctrl inhS__ctrl--prev\" type=\"button\" aria-label=\"Previous\">‹</button>\n        <button class=\"inhS__ctrl inhS__ctrl--next\" type=\"button\" aria-label=\"Next\">›</button>\n\n        <div class=\"inhS__stage\" aria-live=\"polite\">\n          <article class=\"inhS__card is-prev\" id=\"inhS-prev\"></article>\n          <article class=\"inhS__card is-active\" id=\"inhS-active\"></article>\n          <article class=\"inhS__card is-next\" id=\"inhS-next\"></article>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<script>\n(function(){\n  const section = document.getElementById('insurance-how-we-help');\n  if(!section) return;\n\n  const isElementor =\n    document.body.classList.contains('elementor-editor-active') ||\n    document.body.classList.contains('elementor-editor-preview') ||\n    !!document.querySelector('#elementor-editor-wrapper');\n\n  function enter(){ section.classList.add('is-in'); }\n\n  if(isElementor){\n    enter();\n  } else if('IntersectionObserver' in window){\n    const io = new IntersectionObserver((entries)=>{\n      entries.forEach(e=>{\n        if(e.isIntersecting){\n          enter();\n          io.unobserve(section);\n        }\n      });\n    }, { threshold: 0.25 });\n    io.observe(section);\n    setTimeout(()=>{ if(!section.classList.contains('is-in')) enter(); }, 1200);\n  } else {\n    enter();\n  }\n\n  const data = [\n    {\n      navTitle:\"Growth & Strategy\",\n      navHint:\"Future-ready enterprise\",\n      kicker:\"01 · Growth & Strategy\",\n      title:\"Building Future-Ready Insurance Enterprises\",\n      lead:\"We help insurers define clear, executable strategies that balance growth, profitability, and risk.\",\n      label1:\"How we support insurers:\",\n      bullets:[\n        \"Enterprise and business-line strategy formulation\",\n        \"Product portfolio and pricing strategy\",\n        \"Distribution and channel optimisation\",\n        \"Market entry, expansion, and partnership strategies\",\n        \"Strategic program governance and execution assurance\"\n      ],\n      impact:\"Improved growth focus, stronger underwriting discipline, and enhanced profitability.\"\n    },\n    {\n      navTitle:\"Shared Services & GCC Excellence\",\n      navHint:\"Scaling operations\",\n      kicker:\"02 · Shared Services & GCC Excellence\",\n      title:\"Scaling Insurance Operations\",\n      lead:\"Insurers increasingly rely on shared services and GCCs to improve efficiency, consistency, and control.\",\n      label1:\"We help with:\",\n      bullets:[\n        \"Shared services and GCC operating model design\",\n        \"Centralisation of underwriting support, claims, finance, HR, and analytics\",\n        \"Governance frameworks, KPIs, and service management\",\n        \"Capability development for insurance operations leaders\"\n      ],\n      impact:\"Lower operating costs, improved service consistency, and enhanced transparency.\"\n    },\n    {\n      navTitle:\"Tech-Enabled Transformation\",\n      navHint:\"Digitising value chain\",\n      kicker:\"03 · Tech-Enabled Transformation\",\n      title:\"Digitising the Insurance Value Chain\",\n      lead:\"We enable practical, value-led digital transformation across the insurance lifecycle.\",\n      label1:\"Where we support:\",\n      bullets:[\n        \"Core system modernisation roadmap (policy, claims, billing)\",\n        \"Process automation across underwriting, claims, and servicing\",\n        \"Advanced analytics for pricing, risk, fraud, and customer insights\",\n        \"Data platform modernisation and integration\",\n        \"Responsible adoption of AI and decision-support tools\"\n      ],\n      impact:\"Faster turnaround times, reduced leakage, improved decision quality, and better customer experience.\"\n    },\n    {\n      navTitle:\"ESG, Sustainability & Responsible Insurance\",\n      navHint:\"Resilience & trust\",\n      kicker:\"04 · ESG, Sustainability & Responsible Insurance\",\n      title:\"ESG, Sustainability & Responsible Insurance\",\n      lead:\"Sustainability and responsible risk management are becoming central to the insurance mandate.\",\n      label1:\"Our support includes:\",\n      bullets:[\n        \"ESG strategy aligned to regulatory and stakeholder expectations\",\n        \"Climate risk assessment and resilience frameworks\",\n        \"Sustainable underwriting and investment practices\",\n        \"ESG reporting, compliance, and assurance\",\n        \"Governance and ethical risk management enablement\"\n      ],\n      impact:\"Improved risk preparedness, stakeholder trust, and long-term resilience.\"\n    },\n    {\n      navTitle:\"Business Process & Operational Excellence\",\n      navHint:\"Stable systems\",\n      kicker:\"05 · Business Process & Operational Excellence\",\n      title:\"Creating Stable Insurance Systems\",\n      lead:\"Insurance operations demand predictability, control, and customer responsiveness.\",\n      label1:\"Our services include:\",\n      bullets:[\n        \"Lean transformation across underwriting, claims, and servicing\",\n        \"End-to-end value stream optimisation\",\n        \"Cost optimisation and productivity improvement\",\n        \"Target operating model (TOM) design\",\n        \"Standardisation of processes across regions and lines of business\"\n      ],\n      impact:\"Reduced cycle times, improved claims outcomes, lower expense ratios, and higher customer satisfaction.\"\n    }\n  ];\n\n  /* ---------------- DESKTOP SLIDER ---------------- */\n  const navButtons = Array.from(section.querySelectorAll('.inhS__navBtn'));\n  const prevEl = section.querySelector('#inhS-prev');\n  const activeEl = section.querySelector('#inhS-active');\n  const nextEl = section.querySelector('#inhS-next');\n  const btnPrev = section.querySelector('.inhS__ctrl--prev');\n  const btnNext = section.querySelector('.inhS__ctrl--next');\n\n  let idx = 0;\n\n  function cardHTML(d){\n    return `\n      <div class=\"inhS__top\">\n        <p class=\"inhS__kicker\">${d.kicker}</p>\n        <h3 class=\"inhS__cardTitle\">${d.title}</h3>\n      </div>\n      <div class=\"inhS__body\">\n        <p class=\"inhS__lead\">${d.lead}</p>\n        <div class=\"inhS__label\">${d.label1}</div>\n        <ul class=\"inhS__list\">\n          ${d.bullets.map(x=>`<li>${x}</li>`).join('')}\n        </ul>\n        <div class=\"inhS__impact\"><b>Impact:</b> ${d.impact}</div>\n      </div>\n    `;\n  }\n\n  function setActiveNav(i){\n    navButtons.forEach((b,bi)=> b.setAttribute('aria-selected', bi===i ? 'true':'false'));\n  }\n\n  function renderDesktop(){\n    const prevI = (idx - 1 + data.length) % data.length;\n    const nextI = (idx + 1) % data.length;\n\n    if(prevEl) prevEl.innerHTML = cardHTML(data[prevI]);\n    if(activeEl) activeEl.innerHTML = cardHTML(data[idx]);\n    if(nextEl) nextEl.innerHTML = cardHTML(data[nextI]);\n    setActiveNav(idx);\n  }\n\n  function goTo(i){\n    idx = (i + data.length) % data.length;\n    renderDesktop();\n  }\n\n  navButtons.forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      const i = parseInt(btn.getAttribute('data-i'),10);\n      goTo(i);\n    });\n  });\n\n  btnPrev && btnPrev.addEventListener('click', ()=> goTo(idx-1));\n  btnNext && btnNext.addEventListener('click', ()=> goTo(idx+1));\n\n  section.addEventListener('keydown', (e)=>{\n    if(e.key === 'ArrowLeft') goTo(idx-1);\n    if(e.key === 'ArrowRight') goTo(idx+1);\n  });\n\n  renderDesktop();\n\n  /* ---------------- MOBILE ACCORDION ---------------- */\n  const mobileMount = section.querySelector('#inhS-mobile');\n\n  function mobileCard(d, i){\n    return `\n      <div class=\"inhS__mCard\" aria-expanded=\"${i===0 ? 'true':'false'}\" data-i=\"${i}\">\n        <button class=\"inhS__mBtn\" type=\"button\" aria-label=\"${d.navTitle}\">\n          <div class=\"inhS__mLeft\">\n            <span class=\"inhS__navMark\" aria-hidden=\"true\"></span>\n            <div style=\"min-width:0\">\n              <p class=\"inhS__mTitle\">${d.navTitle}</p>\n              <p class=\"inhS__mHint\">${d.navHint}</p>\n            </div>\n          </div>\n          <span class=\"inhS__mChevron\" aria-hidden=\"true\">⌄</span>\n        </button>\n\n        <div class=\"inhS__mAcc\">\n          <div class=\"inhS__mContent\">\n            <div class=\"inhS__mTop\">\n              <p class=\"inhS__mKicker\">${d.kicker}</p>\n              <h3 class=\"inhS__mCardTitle\">${d.title}</h3>\n            </div>\n            <div class=\"inhS__mBody\">\n              <p class=\"inhS__mLead\">${d.lead}</p>\n              <div class=\"inhS__mLabel\">${d.label1}</div>\n              <ul class=\"inhS__mList\">\n                ${d.bullets.map(x=>`<li>${x}</li>`).join('')}\n              </ul>\n              <div class=\"inhS__mImpact\"><b>Impact:</b> ${d.impact}</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    `;\n  }\n\n  function renderMobile(){\n    if(!mobileMount) return;\n    mobileMount.innerHTML = data.map((d,i)=>mobileCard(d,i)).join('');\n\n    const cards = Array.from(mobileMount.querySelectorAll('.inhS__mCard'));\n    cards.forEach(card=>{\n      const btn = card.querySelector('.inhS__mBtn');\n      btn.addEventListener('click', ()=>{\n        const isOpen = card.getAttribute('aria-expanded') === 'true';\n        cards.forEach(c=>c.setAttribute('aria-expanded','false'));\n        card.setAttribute('aria-expanded', isOpen ? 'false' : 'true');\n      });\n    });\n  }\n\n  renderMobile();\n})();\n</script>\n\n<!-- ===================== INSURANCE — WHY WORK WITH US (IMAGE LEFT) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#3C4160;\n}\n\n/* SECTION */\n.inw, .inw *{box-sizing:border-box;}\n.inw{\n  padding:96px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  background:\n    radial-gradient(circle at 18% 0%, rgba(98,90,216,.08), transparent 55%),\n    radial-gradient(circle at 95% 30%, rgba(49,59,134,.08), transparent 55%),\n    radial-gradient(circle at 70% 110%, rgba(2,12,79,.06), transparent 60%),\n    rgba(49,59,134,.03);\n}\n\n.inw__inner{\n  max-width:1200px;\n  margin:0 auto;\n  display:grid;\n  grid-template-columns:1.05fr 0.95fr; /* image slightly wider */\n  gap:44px;\n  align-items:stretch; /* equal height */\n}\n\n/* IMAGE COLUMN */\n.inw__imageWrap{\n  position:relative;\n  border-radius:26px;\n  overflow:hidden;\n  min-height:460px;\n  box-shadow:0 22px 54px rgba(0,0,0,.10);\n}\n\n.inw__imageWrap img{\n  position:absolute;\n  inset:0;\n  width:100%;\n  height:100%;\n  object-fit:cover; /* ✅ full image, no gap */\n  display:block;\n}\n\n/* subtle brand overlay */\n.inw__imageWrap::after{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  background:\n    linear-gradient(180deg, rgba(2,12,79,.18), rgba(2,12,79,.08) 55%, rgba(255,255,255,0) 100%),\n    radial-gradient(circle at 20% 20%, rgba(98,90,216,.20), transparent 60%),\n    radial-gradient(circle at 80% 35%, rgba(31,156,228,.16), transparent 60%);\n  pointer-events:none;\n}\n\n/* CONTENT COLUMN */\n.inw__content{\n  display:flex;\n  flex-direction:column;\n  justify-content:center;\n}\n\n.inw__eyebrow{\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:800;\n  margin:0 0 10px;\n}\n\n.inw__title{\n  font-size:clamp(32px,3.6vw,46px);\n  line-height:1.1;\n  font-weight:900;\n  color:var(--navy);\n  margin:0 0 18px;\n}\n\n/* MANIFESTO LIST */\n.inw__list{\n  list-style:none;\n  margin:0;\n  padding:0;\n  display:grid;\n  gap:18px;\n  position:relative;\n}\n\n/* vertical guide */\n.inw__list::before{\n  content:\"\";\n  position:absolute;\n  left:14px;\n  top:6px;\n  bottom:6px;\n  width:2px;\n  background:linear-gradient(180deg, rgba(98,90,216,.45), rgba(31,156,228,.35));\n  opacity:.6;\n}\n\n.inw__item{\n  position:relative;\n  padding-left:46px;\n}\n\n.inw__dot{\n  position:absolute;\n  left:6px;\n  top:4px;\n  width:18px;\n  height:18px;\n  border-radius:50%;\n  background:#fff;\n  border:1px solid rgba(49,59,134,.25);\n}\n\n.inw__dot::after{\n  content:\"\";\n  position:absolute;\n  inset:4px;\n  border-radius:50%;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.12);\n}\n\n.inw__h{\n  margin:0 0 4px;\n  font-size:16px;\n  font-weight:800;\n  color:var(--navy);\n}\n\n.inw__p{\n  margin:0;\n  font-size:14.8px;\n  line-height:1.75;\n  color:#3C4160;\n}\n\n/* MOBILE */\n@media(max-width:980px){\n  .inw{padding:78px 18px;}\n  .inw__inner{grid-template-columns:1fr; gap:26px;}\n  .inw__imageWrap{min-height:260px;}\n  .inw__list::before{left:12px;}\n}\n</style>\n\n<section class=\"inw\" id=\"insurance-why\">\n  <div class=\"inw__inner\">\n\n    <!-- IMAGE LEFT -->\n    <div class=\"inw__imageWrap\">\n      <img\n        src=\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\"\n        alt=\"Insurance transformation\"\n      />\n    </div>\n\n    <!-- CONTENT RIGHT -->\n    <div class=\"inw__content\">\n      <p class=\"inw__eyebrow\">Insurance Sector</p>\n      <h2 class=\"inw__title\">Why Insurance Organisations Work With Us</h2>\n\n      <ul class=\"inw__list\">\n        <li class=\"inw__item\">\n          <span class=\"inw__dot\"></span>\n          <p class=\"inw__h\">Strategy and Execution as One System</p>\n          <p class=\"inw__p\">We connect leadership intent directly to underwriting, claims, and customer outcomes.</p>\n        </li>\n\n        <li class=\"inw__item\">\n          <span class=\"inw__dot\"></span>\n          <p class=\"inw__h\">Deep Understanding of Regulated, Risk-Intensive Environments</p>\n          <p class=\"inw__p\">Our approaches are designed with compliance, control, and resilience at the core.</p>\n        </li>\n\n        <li class=\"inw__item\">\n          <span class=\"inw__dot\"></span>\n          <p class=\"inw__h\">Digital That Enhances Judgment</p>\n          <p class=\"inw__p\">Technology deployed to strengthen risk decisions—not replace them.</p>\n        </li>\n\n        <li class=\"inw__item\">\n          <span class=\"inw__dot\"></span>\n          <p class=\"inw__h\">Integrated, Proven Methodologies</p>\n          <p class=\"inw__p\">Strategy, Lean, analytics, digital, TOM, ESG, and change—working together.</p>\n        </li>\n\n        <li class=\"inw__item\">\n          <span class=\"inw__dot\"></span>\n          <p class=\"inw__h\">Outcome-Driven Engagements</p>\n          <p class=\"inw__p\">Every engagement is tied to growth, cost, risk, or customer experience metrics.</p>\n        </li>\n      </ul>\n    </div>\n\n  </div>\n</section>\n\n<!-- ===================== INSURANCE — FINAL CTA (WHITE BACKGROUND STRIP) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#3C4160;\n  --line:rgba(49,59,134,.16);\n}\n\n.in-cta, .in-cta *{box-sizing:border-box;}\n.in-cta{\n  padding:84px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  background:#ffffff; /* ✅ white background */\n}\n\n.in-cta__inner{\n  max-width:1200px;\n  margin:0 auto;\n}\n\n.in-cta__bar{\n  border:1px solid rgba(49,59,134,.16);\n  border-radius:26px;\n  background:rgba(255,255,255,.98);\n  box-shadow:0 22px 54px rgba(0,0,0,.08);\n  padding:28px 28px;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:22px;\n}\n\n.in-cta__left{\n  min-width:0;\n  max-width:820px;\n}\n\n.in-cta__kicker{\n  margin:0 0 10px;\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:800;\n}\n\n.in-cta__title{\n  margin:0 0 10px;\n  font-size:clamp(26px,3.2vw,38px);\n  line-height:1.15;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.in-cta__text{\n  margin:0;\n  font-size:15.5px;\n  line-height:1.75;\n  color:var(--muted);\n}\n\n/* small “signal” pill */\n.in-cta__pill{\n  display:inline-flex;\n  align-items:center;\n  gap:10px;\n  padding:9px 12px;\n  border-radius:999px;\n  border:1px solid rgba(49,59,134,.18);\n  background:rgba(49,59,134,.04);\n  color:var(--indigo);\n  font-weight:800;\n  font-size:12px;\n  margin-top:14px;\n  flex-wrap:wrap;\n}\n\n.in-cta__dot{\n  width:9px;height:9px;border-radius:999px;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.10);\n}\n\n.in-cta__right{\n  flex:0 0 auto;\n  display:flex;\n  gap:12px;\n  flex-wrap:wrap;\n  justify-content:flex-end;\n}\n\n.in-cta__btn{\n  height:46px;\n  padding:0 18px;\n  border-radius:999px;\n  display:inline-flex;\n  align-items:center;\n  justify-content:center;\n  gap:10px;\n  font-size:14px;\n  font-weight:800;\n  text-decoration:none;\n  transition:.2s ease;\n  white-space:nowrap;\n}\n\n.in-cta__btn--primary{\n  background:var(--violet);\n  color:#fff;\n  border:1px solid var(--violet);\n  box-shadow:0 12px 26px rgba(98,90,216,.22);\n}\n.in-cta__btn--primary:hover{\n  background:var(--accent);\n  border-color:var(--accent);\n  transform:translateY(-1px);\n}\n\n.in-cta__btn--ghost{\n  background:#fff;\n  color:var(--navy);\n  border:1px solid rgba(49,59,134,.22);\n}\n.in-cta__btn--ghost:hover{\n  background:rgba(49,59,134,.04);\n  transform:translateY(-1px);\n}\n\n@media (max-width:980px){\n  .in-cta{padding:70px 18px;}\n  .in-cta__bar{\n    padding:22px;\n    flex-direction:column;\n    align-items:flex-start;\n  }\n  .in-cta__right{justify-content:flex-start;}\n}\n</style>\n\n<section class=\"in-cta\" id=\"insurance-cta\">\n  <div class=\"in-cta__inner\">\n\n    <div class=\"in-cta__bar\">\n      <div class=\"in-cta__left\">\n        <p class=\"in-cta__kicker\">Next steps</p>\n        <h2 class=\"in-cta__title\">Let’s Build the Next-Generation Insurance Enterprise</h2>\n        <p class=\"in-cta__text\">\n          From strategy and shared services to digital enablement, ESG, and operational excellence, we partner with\n          insurers to build enterprises that are trusted, resilient, and built for the future.\n        </p>\n\n        <div class=\"in-cta__pill\">\n          <span class=\"in-cta__dot\" aria-hidden=\"true\"></span>\n          Strategy • Shared Services • Digital • ESG • Operational Excellence\n        </div>\n      </div>\n\n      <div class=\"in-cta__right\">\n        <a class=\"in-cta__btn in-cta__btn--ghost\" href=\"/contact-us\">Talk to us</a>\n        <a class=\"in-cta__btn in-cta__btn--primary\" href=\"/contact-us\">Request a consultation →</a>\n      </div>\n    </div>\n\n  </div>\n</section>";
